//! Central declaration of every conditional-compilation alias used by the
//! crate. Keeping the raw `target_*` predicates here (and only here) means the
//! rest of the codebase reads in terms of intent:
//!
//! ```ignore
//! #[cfg(unix_family)]
//! fn ... { }
//! ```
//!
//! rather than spelling out long `any(target_os = "...", ...)` chains.

use cfg_aliases::cfg_aliases;

fn main() {
    // Tell cargo to re-run whenever this file changes.
    println!("cargo:rerun-if-changed=build.rs");

    cfg_aliases! {
        // ---- Operating-system families --------------------------------
        unix_family:    { any(target_family = "unix") },
        windows_family: { target_family = "windows" },
        wasm_family:    { target_family = "wasm" },

        // ---- Coarse target classes ------------------------------------
        desktop: { any(
            target_os = "linux",
            target_os = "macos",
            target_os = "windows",
        ) },
        mobile: { any(target_os = "android", target_os = "ios") },

        // ---- Capabilities ---------------------------------------------
        has_std:        { feature = "std" },
        has_threads:    { all(has_std, not(wasm_family)) },
        has_atomic_ptr: { all(has_std, target_has_atomic = "ptr") },
        has_page_size:  { any(unix_family, windows_family) },
    }
}
```

