#![deny(unexpected_cfgs)]
#![warn(missing_docs)]

#[cfg(feature = "std")]
extern crate std;

pub mod platform;

pub use platform::{platform, Family, Platform};

/// The version of this crate, taken from `Cargo.toml` at compile time.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");
