//! Central declaration of every conditional-compilation alias used by the
//! crate.
//!
//! Keeping the raw `target_*` predicates here — and only here — lets the rest
//! of the codebase read in terms of *intent*:
//!
//! ```ignore
//! #[cfg(unix_family)]
//! fn something() { /* ... */ }
//! ```
//!
//! instead of long, error-prone chains such as
//! `any(target_os = "linux", target_os = "macos", ...)`.
//!
//! To add a platform, add/extend an alias here and add a backend under
//! `src/platform/`. Nothing else should need to change.

use cfg_aliases::cfg_aliases;

fn main() {
    println!("cargo:rerun-if-changed=build.rs");

    cfg_aliases! {
        // ---- Operating-system families --------------------------------
        unix_family:    { any(target_family = "unix") },
        windows_family: { target_family = "windows" },
        wasm_family:    { target_family = "wasm" },

        // ---- Coarse target classes ------------------------------------
        desktop: { any(
            target_os = "linux",
            target_os = "macos",
            target_os = "windows",
        ) },
        mobile: { any(target_os = "android", target_os = "ios") },

        // ---- Architecture ---------------------------------------------
        arch_64: { target_pointer_width = "64" },

        // ---- Capabilities ---------------------------------------------
        has_std:        { feature = "std" },
        has_threads:    { all(has_std, not(wasm_family)) },
        has_atomic_ptr: { all(has_std, target_has_atomic = "ptr") },
        has_page_size:  { any(unix_family, windows_family) },
    }
}

//! `xplat` — a small cross-platform library scaffold.
//!
//! # Conditional-compilation strategy
//!
//! Raw target detection is confined to exactly two places:
//!
//! 1. [`build.rs`](../../build.rs) defines *semantic cfg aliases* such as
//!    `unix_family` or `has_threads`.
//! 2. [`platform`] maps those aliases onto concrete backends.
//!
//! Everywhere else, write `#[cfg(unix_family)]` — never
//! `#[cfg(target_os = "linux")]`. This keeps conditional blocks short and
//! readable and turns "which platforms exist?" into a single-file question.
//!
//! ```
//! let info = xplat::platform();
//! assert!(!info.name.is_empty());
//! ```

#![cfg_attr(not(feature = "std"), no_std)]
#![deny(unexpected_cfgs)]
#![warn(missing_docs)]

#[cfg(feature = "std")]
extern crate std;

pub mod platform;

pub use platform::{platform, Family, Platform};

/// The version of this crate, taken from `Cargo.toml` at compile time.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");

//! Platform detection and dispatch.
//!
//! This module is the **only** place that resolves the semantic `cfg` aliases
//! from `build.rs` into concrete code. It uses [`cfg_if`] to keep the
//! if/else chain flat instead of stacking `#[cfg(...)]` attributes.
//!
//! Adding a platform means editing this dispatch and adding a backend file
//! next to it; callers keep using the same API.

cfg_if::cfg_if! {
    if #[cfg(unix_family)] {
        mod unix;
        use unix as backend;
    } else if #[cfg(windows_family)] {
        mod windows;
        use windows as backend;
    } else if #[cfg(wasm_family)] {
        mod wasm;
        use wasm as backend;
    } else {
        mod fallback;
        use fallback as backend;
    }
}

pub use backend::Backend;

/// The operating-system family the crate was compiled for.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Family {
    /// Unix-like systems (`unix_family`).
    Unix,
    /// Windows (`windows_family`).
    Windows,
    /// WebAssembly (`wasm_family`).
    Wasm,
    /// Anything not covered by a dedicated backend.
    Other,
}

/// Which [`Family`] this build targets.
pub const FAMILY: Family = Backend::FAMILY;

/// The line-ending sequence used by the current platform.
pub const NEWLINE: &str = Backend::NEWLINE;

/// The path separator used by the current platform.
pub const PATH_SEPARATOR: char = Backend::PATH_SEPARATOR;

/// A snapshot of properties of the platform this crate was compiled for.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub struct Platform {
    /// Backend name, e.g. `"unix"` or `"windows"`.
    pub name: &'static str,
    /// Coarse operating-system family.
    pub family: Family,
    /// Whether pointers are 64 bits wide (`arch_64`).
    pub is_64_bit: bool,
    /// Whether the target is expected to have threads (`has_threads`).
    pub has_threads: bool,
}

/// Returns a [`Platform`] describing the current compilation target.
///
/// This is a `const fn`, so it can be used to initialise constants.
#[must_use]
pub const fn platform() -> Platform {
    Platform {
        name: Backend::NAME,
        family: Backend::FAMILY,
        is_64_bit: cfg!(arch_64),
        has_threads: cfg!(has_threads),
    }
}

/// Operating-system page size, in bytes.
///
/// Only available on platforms with a dedicated, syscall-backed backend
/// (`has_page_size`). Portable targets use the [`fallback`](self) backend and
/// do not expose this function.
#[cfg(has_page_size)]
pub use backend::page_size;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn platform_is_self_consistent() {
        let info = platform();
        assert!(!info.name.is_empty());
        assert_eq!(info.family, FAMILY);
    }

    #[test]
    fn separator_and_newline_are_sane() {
        assert!(['/', '\\'].contains(&PATH_SEPARATOR));
        assert!(["\n", "\r\n"].contains(&NEWLINE));
    }
}

