//! Backend for Unix-like systems (`unix_family`).
//!
//! Compiled only when the `unix_family` alias from `build.rs` is set, so this
//! file contains no raw `target_*` checks of its own.

use crate::platform::Family;

/// Marker type representing the Unix backend.
#[derive(Debug, Clone, Copy, Default)]
pub struct Backend;

impl Backend {
    /// Backend name.
    pub const NAME: &'static str = "unix";
    /// Operating-system family.
    pub const FAMILY: Family = Family::Unix;
    /// Native line ending.
    pub const NEWLINE: &'static str = "\n";
    /// Native path separator.
    pub const PATH_SEPARATOR: char = '/';
}

/// Operating-system page size, in bytes.
///
/// Provided by the `libc` dependency declared under
/// `[target.'cfg(unix)'.dependencies]` in `Cargo.toml`.
#[must_use]
pub fn page_size() -> usize {
    // `_SC_PAGESIZE` is always a valid name; on failure fall back to 4096.
    let value = unsafe { libc::sysconf(libc::_SC_PAGESIZE) };
    if value > 0 {
        value as usize
    } else {
        4096
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn page_size_is_a_power_of_two() {
        let size = page_size();
        assert!(size.is_power_of_two(), "unexpected page size: {size}");
    }

    #[test]
    fn separator_is_forward_slash() {
        assert_eq!(Backend::PATH_SEPARATOR, '/');
    }
}

//! Backend for Windows (`windows_family`).
//!
//! Compiled only when the `windows_family` alias from `build.rs` is set.

use crate::platform::Family;

/// Marker type representing the Windows backend.
#[derive(Debug, Clone, Copy, Default)]
pub struct Backend;

impl Backend {
    /// Backend name.
    pub const NAME: &'static str = "windows";
    /// Operating-system family.
    pub const FAMILY: Family = Family::Windows;
    /// Native line ending.
    pub const NEWLINE: &'static str = "\r\n";
    /// Native path separator.
    pub const PATH_SEPARATOR: char = '\\';
}

/// Operating-system page size, in bytes.
///
/// Provided by the `windows-sys` dependency declared under
/// `[target.'cfg(windows)'.dependencies]` in `Cargo.toml`.
#[must_use]
pub fn page_size() -> usize {
    use windows_sys::Win32::System::SystemInformation::{GetSystemInfo, SYSTEM_INFO};

    // SAFETY: `GetSystemInfo` only writes into the pointer it is given; a
    // zeroed `SYSTEM_INFO` is a valid destination.
    let mut info: SYSTEM_INFO = unsafe { core::mem::zeroed() };
    unsafe { GetSystemInfo(&mut info) };
    info.dwPageSize as usize
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn page_size_is_a_power_of_two() {
        let size = page_size();
        assert!(size.is_power_of_two(), "unexpected page size: {size}");
    }

    #[test]
    fn separator_is_backslash() {
        assert_eq!(Backend::PATH_SEPARATOR, '\\');
    }
}

//! Backend for WebAssembly (`wasm_family`).
//!
//! Compiled only when the `wasm_family` alias from `build.rs` is set.

use crate::platform::Family;

/// Marker type representing the WebAssembly backend.
#[derive(Debug, Clone, Copy, Default)]
pub struct Backend;

impl Backend {
    /// Backend name.
    pub const NAME: &'static str = "wasm";
    /// Operating-system family.
    pub const FAMILY: Family = Family::Wasm;
    /// Line ending used by the platform.
    pub const NEWLINE: &'static str = "\n";
    /// Path separator used by the platform.
    pub const PATH_SEPARATOR: char = '/';
}

//! Portable fallback backend.
//!
//! Compiled for any target that is not Unix, Windows or WebAssembly. It makes
//! no operating-system assumptions, which keeps the crate buildable for new or
//! exotic targets without touching the rest of the code.

use crate::platform::Family;

/// Marker type representing the portable fallback backend.
#[derive(Debug, Clone, Copy, Default)]
pub struct Backend;

impl Backend {
    /// Backend name.
    pub const NAME: &'static str = "fallback";
    /// Operating-system family.
    pub const FAMILY: Family = Family::Other;
    /// Line ending used by the platform.
    pub const NEWLINE: &'static str = "\n";
    /// Path separator used by the platform.
    pub const PATH_SEPARATOR: char = '/';
}

//! Integration tests.
//!
//! Note that build-script `cfg` aliases (e.g. `unix_family`) are applied to
//! integration tests as well, so the tests read the same way as the crate.

use xplat::{platform, Family, PATH_SEPARATOR};

#[test]
fn reports_a_known_family() {
    let info = platform();
    assert!(!info.name.is_empty());
    assert!(matches!(
        info.family,
        Family::Unix | Family::Windows | Family::Wasm | Family::Other
    ));
}

#[cfg(unix_family)]
#[test]
fn unix_family_selects_unix_backend() {
    assert_eq!(platform().family, Family::Unix);
    assert_eq!(platform().name, "unix");
    assert_eq!(PATH_SEPARATOR, '/');
}

#[cfg(windows_family)]
#[test]
fn windows_family_selects_windows_backend() {
    assert_eq!(platform().family, Family::Windows);
    assert_eq!(platform().name, "windows");
    assert_eq!(PATH_SEPARATOR, '\\');
}

#[cfg(has_page_size)]
#[test]
fn page_size_is_available_and_sane() {
    let size = xplat::platform::page_size();
    assert!(size >= 4096, "unexpected page size: {size}");
    assert!(size.is_power_of_two(), "unexpected page size: {size}");
}

